self.addEventListener('install',event=>event.waitUntil((async()=>{
 try{
  const cache=await caches.open(CACHE);
  await cache.addAll(FILES.map(p=>new Request(new URL(p,self.registration.scope),{cache:'reload'})));
  for(const [name,source]of Object.entries(MODULES))await cache.put(new URL('./'+name,self.registration.scope),new Response(source,{headers:{'Content-Type':(name.endsWith('.css')?'text/css':'text/javascript')+'; charset=utf-8'}}));
  // Existing clients keep their version until closed or update explicitly accepted.
 }catch(error){await caches.delete(CACHE);throw error;}
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
 await self.clients.claim();
 const keys=await caches.keys();
 await Promise.all(keys.filter(key=>key.startsWith(PREFIX)&&key!==CACHE).map(key=>caches.delete(key)));
})()));
self.addEventListener('fetch',event=>{
 const url=new URL(event.request.url);
 if(event.request.method!=='GET'||url.origin!==self.location.origin||!url.href.startsWith(self.registration.scope))return;
 event.respondWith((async()=>{
  const cache=await caches.open(CACHE);
  const hit=await cache.match(event.request,{ignoreSearch:true});
  if(hit)return hit;
  if(event.request.mode==='navigate')return cache.match(new URL('./index.html',self.registration.scope));
  return fetch(event.request);
 })());
});

self.addEventListener('message',event=>{
 if(event.data?.type==='SKIP_WAITING')event.waitUntil(self.skipWaiting());
});
